-- All ids are UUIDv7 generated by the API (time-ordered), so "order by id" is chronological.

create table users (
    id           uuid primary key,
    google_sub   text not null unique,
    email        text not null,
    display_name text not null,
    avatar_url   text not null default '',
    role         text not null default 'member' check (role in ('admin', 'member')),
    created_at   timestamptz not null default now()
);

-- Opaque session tokens; only the SHA-256 of the token is stored.
create table sessions (
    id           uuid primary key,
    user_id      uuid not null references users (id) on delete cascade,
    token_hash   bytea not null unique,
    created_at   timestamptz not null default now(),
    expires_at   timestamptz not null,
    last_used_at timestamptz not null default now()
);
create index sessions_user_id_idx on sessions (user_id);

create table invites (
    code       text primary key,
    created_by uuid not null references users (id) on delete cascade,
    max_uses   int check (max_uses is null or max_uses > 0), -- null = unlimited
    uses       int not null default 0,
    expires_at timestamptz,                                   -- null = never
    created_at timestamptz not null default now()
);

create table channels (
    id         uuid primary key,
    kind       text not null check (kind in ('text', 'voice')),
    name       text not null check (length(name) between 1 and 100),
    position   int not null default 0,
    created_at timestamptz not null default now()
);

create table messages (
    id          uuid primary key,
    channel_id  uuid not null references channels (id) on delete cascade,
    author_id   uuid not null references users (id) on delete cascade,
    content     text not null default '' check (length(content) <= 4000),
    -- [{key, name, content_type, size, width?, height?}]
    attachments jsonb not null default '[]',
    created_at  timestamptz not null default now(),
    edited_at   timestamptz
);
create index messages_channel_id_idx on messages (channel_id, id desc);
